effect.shader:
// ---- a ponte Nova <-> Node (tools/nodeluzes/gerar.py)
vec2 nvUV;   // o vs_TEXCOORD0 dos programas do Node: o acScreenNorm, ou outro ponto que o passe escolhe
vec3 nvLinear(vec3 c) { return mix(c / 12.92, pow((c + 0.055) / 1.055, vec3(2.4)), step(0.04045, c)); }
vec3 nvGama(vec3 c) { return mix(c * 12.92, 1.055 * pow(c, vec3(1.0 / 2.4)) - 0.055, step(0.0031308, c)); }
// O passe 0: a camada como o Node a guarda (pre-multiplicada, luz linear; o buffer `pre` e sRGB de 8 bits).
vec4 nvCor(vec4 c) { return vec4(nvLinear(c.rgb), c.a); }
vec4 nvEntrada() { vec4 c = texture(inputImg, acScreenNorm); return vec4(nvLinear(c.rgb) * c.a, c.a); }
// A saída do Node (pre-multiplicada, linear, presa a 0..1 como o RT de 8 bits) para a cor reta do Nova. A luz que
// o Node soma acima do alfa (o brilho fora do recorte) vira alfa: a = max(alfa, r, g, b). NaN (0 x infinito na
// conta do Node) vira 0, como no RT de 8 bits dele; a escolha pelo bvec não faz conta com o NaN.
vec4 nvSaida(vec4 p) {
    p = mix(vec4(0.0), min(p, vec4(1.0)), greaterThanEqual(p, vec4(0.0)));
    float a = max(p.a, max(p.r, max(p.g, p.b)));
    return a > 0.0 ? vec4(nvGama(p.rgb / a), a) : vec4(0.0);
}
// A máscara interna do Node (o editor de máscara dele) fica desligada, como no padrão.
#define _use_inner_mask 0
#define _b_clip_mask 0
#define _show_inner_mask 0
// O AEStarGlow (XJINE StarGlow): RTs de (W / _blur) x (H / _blur), W x H a composição. Aqui os buffers ficam na
// metade (o _blur mínimo, 2) e cada texel guarda o valor da célula da grade do Node em que cai (`nvCentro`); a leitura
// do Node (linear entre os centros das células) é refeita por `nvLe` quando a grade não é a do buffer.
float vs_TEXCOORD1;   // 4^(iteração - 1): o passo e o expoente do peso
vec2 vs_TEXCOORD2;    // o passo em UV: 4^(it-1) x _offset / _resolution
#define _attenuation max(min(sqrt(_length), 0.99), 1e-6)
int nvN() { return clamp(int(_streaks), 1, 6); }
vec2 nvGrade() { return max(floor(vec2(textureSize(pre, 0)) / max(trunc(_blur), 2.0)), vec2(1.0)); }
vec2 nvCentro(vec2 uv) { vec2 g = nvGrade(); return (floor(uv * g) + 0.5) / g; }
vec4 nvLe(sampler2D t, vec2 uv) {
    vec2 g = nvGrade();
    ivec2 tam = textureSize(t, 0);
    if (all(equal(g, vec2(tam)))) return texture(t, uv);
    vec2 p = uv * g - 0.5, k = floor(p), f = p - k;
    vec2 c0 = clamp((k + 0.5) / g, 0.5 / g, 1.0 - 0.5 / g), c1 = clamp((k + 1.5) / g, 0.5 / g, 1.0 - 0.5 / g);
    vec2 tb = vec2(tam);
    ivec2 m = tam - 1;
    vec4 a = texelFetch(t, clamp(ivec2(c0 * tb), ivec2(0), m), 0);
    vec4 b = texelFetch(t, clamp(ivec2(vec2(c1.x, c0.y) * tb), ivec2(0), m), 0);
    vec4 c = texelFetch(t, clamp(ivec2(vec2(c0.x, c1.y) * tb), ivec2(0), m), 0);
    vec4 d = texelFetch(t, clamp(ivec2(c1 * tb), ivec2(0), m), 0);
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
// O raio k (1..N) do C#: ângulo = trunc(_angle) + 360/N x k; _offset = AngleAxis(ângulo, frente) x Vector2.down.
void nvRaio(int k, int it) {
    float a = radians(trunc(_angle) + 360.0 / float(nvN()) * float(k));
    vs_TEXCOORD1 = exp2(2.0 * float(it - 1));
    vs_TEXCOORD2 = vs_TEXCOORD1 * vec2(sin(a), -cos(a)) / acTamanhoDaTela;
}

// ---- programa 0 do Node: NodeVideo_Effect_star_glow_1.glsl
vec4 p0_x0;
vec2 p0_x1;
void p0_main()
{
    p0_x0 = texture(pre, nvUV.xy);
    p0_x1.xy = vec2(_threshold, _intensity) * vec2(_threshold, _intensity);
    p0_x0 = (-p0_x1.xxxx) * p0_x1.xxxx + p0_x0;
    p0_x0 = max(p0_x0, vec4(0.0, 0.0, 0.0, 0.0));
    p0_x0 = p0_x0 * p0_x1.yyyy;
    fragColor = p0_x0 * vec4(vec4(_intensity, _intensity, _intensity, _intensity));
    return;
}

// ---- programa 1 do Node: NodeVideo_Effect_star_glow_2.glsl
float p1_x0;
vec2 p1_x1;
vec3 p1_x2;
vec3 p1_x3;
int p1_xi7;
float p1_x10;
bool p1_xb10;
void p1_main(sampler2D _blur_tex)
{
    p1_x0 = log2(abs(_attenuation));
    p1_x3.x = float(0.0);
    p1_x3.y = float(0.0);
    p1_x3.z = float(0.0);
    p1_x1.xy = nvUV.xy;
    for(int p1_xi_loop_1 = 0 ; p1_xi_loop_1<int(_quality) ; p1_xi_loop_1++)
    {
        p1_x2.xyz = nvLe(_blur_tex, p1_x1.xy).xyz;
        p1_x10 = float(p1_xi_loop_1);
        p1_x10 = p1_x10 * vs_TEXCOORD1;
        p1_x10 = p1_x0 * p1_x10;
        p1_x10 = exp2(p1_x10);
        p1_x2.xyz = vec3(p1_x10) * p1_x2.xyz;
        p1_x2.xyz = clamp(p1_x2.xyz, 0.0, 1.0);
        p1_x3.xyz = p1_x3.xyz + p1_x2.xyz;
        p1_x1.xy = p1_x1.xy + vs_TEXCOORD2.xy;
    }
    fragColor.xyz = p1_x3.xyz;
    fragColor.w = 1.0;
    return;
}

// ---- programa 2 do Node: NodeVideo_Effect_star_glow_3.glsl
void p2_main(sampler2D _blur_tex)
{
    fragColor = nvLe(_blur_tex, nvUV.xy);
    return;
}

// ---- programa 3 do Node: NodeVideo_Effect_star_glow_4.glsl
vec4 p3_x0;
vec4 p3_x1;
float p3_x2;
bvec3 p3_xb2;
vec4 p3_x3;
vec4 p3_x4;
vec4 p3_x5;
float p3_x14;
void p3_main(sampler2D _composite_tex)
{
    p3_x0 = texture(pre, nvUV.xy);
    p3_x1 = nvLe(_composite_tex, nvUV.xy);
    p3_xb2.xyz = equal(ivec4(ivec4(int(_blend_mode), int(_blend_mode), int(_blend_mode), int(_blend_mode))), ivec4(1, 3, 0, 0)).xyz;
    {
        bvec3 hlslcc_orTemp = p3_xb2;
        hlslcc_orTemp.x = p3_xb2.y || p3_xb2.x;
        hlslcc_orTemp.y = p3_xb2.x || p3_xb2.z;
        p3_xb2 = hlslcc_orTemp;
    }
    p3_x14 = p3_x1.y + p3_x1.x;
    p3_x14 = p3_x1.z + p3_x14;
    p3_x14 = p3_x14 * 0.333299994;
    p3_x3.xyz = vec3(p3_x14) * nvCor(_composite_color).xyz;
    p3_x1.xyz = (p3_xb2.x) ? p3_x3.xyz : p3_x1.xyz;
    p3_x3 = p3_x0 + p3_x1;
    p3_x4 = p3_x3;
    p3_x4 = clamp(p3_x4, 0.0, 1.0);
    p3_x1 = p3_x0 * p3_x1;
    p3_x1 = clamp(p3_x1, 0.0, 1.0);
    p3_x1 = (-p3_x1) + p3_x3;
    p3_x1 = clamp(p3_x1, 0.0, 1.0);
    p3_x1 = (p3_xb2.y) ? p3_x4 : p3_x1;
    if(int(_use_inner_mask) != 0) {
        p3_xb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        p3_x3 = (p3_xb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : p3_x1;
        p3_x4 = texture(pre, nvUV.xy);
        p3_x5 = (-p3_x4) + vec4(1.0, 1.0, 1.0, 1.0);
        p3_x0 = p3_x0 * p3_x5;
        p3_x0 = p3_x3 * p3_x4 + p3_x0;
        p3_x2 = p3_x4.x * p3_x0.w;
        fragColor.w = (p3_xb2.y) ? p3_x2 : p3_x0.w;
        fragColor.xyz = p3_x0.xyz;
    } else {
        fragColor = p3_x1;
    }
    return;
}

void main()
{
    nvUV = acScreenNorm;
    if (acPass == 0) { fragColor = nvEntrada(); return; }
    if (acPass == 1) { nvUV = nvCentro(acScreenNorm); p0_main(); return; }
    if (acPass == 2) { if (1 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(1, 1); nvUV = nvCentro(acScreenNorm); p1_main(bright); return; }
    if (acPass == 3) { if (1 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(1, 2); nvUV = nvCentro(acScreenNorm); p1_main(bA); return; }
    if (acPass == 4) { if (1 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(1, 3); nvUV = nvCentro(acScreenNorm); p1_main(bB); return; }
    if (acPass == 5) { if (1 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(1, 4); nvUV = nvCentro(acScreenNorm); p1_main(bA); return; }
    if (acPass == 6) { if (1 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(1, 5); nvUV = nvCentro(acScreenNorm); p1_main(bB); return; }
    if (acPass == 7) { nvUV = nvCentro(acScreenNorm); p2_main(bA); return; }
    if (acPass == 8) { if (2 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(2, 1); nvUV = nvCentro(acScreenNorm); p1_main(bright); return; }
    if (acPass == 9) { if (2 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(2, 2); nvUV = nvCentro(acScreenNorm); p1_main(bA); return; }
    if (acPass == 10) { if (2 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(2, 3); nvUV = nvCentro(acScreenNorm); p1_main(bB); return; }
    if (acPass == 11) { if (2 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(2, 4); nvUV = nvCentro(acScreenNorm); p1_main(bA); return; }
    if (acPass == 12) { if (2 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(2, 5); nvUV = nvCentro(acScreenNorm); p1_main(bB); return; }
    if (acPass == 13) { if (2 > nvN()) { fragColor = texture(cA, acScreenNorm); return; } nvUV = nvCentro(acScreenNorm); p2_main(bA); vec4 c = texture(cA, acScreenNorm); fragColor = fragColor + c - fragColor * c; return; }
    if (acPass == 14) { if (3 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(3, 1); nvUV = nvCentro(acScreenNorm); p1_main(bright); return; }
    if (acPass == 15) { if (3 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(3, 2); nvUV = nvCentro(acScreenNorm); p1_main(bA); return; }
    if (acPass == 16) { if (3 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(3, 3); nvUV = nvCentro(acScreenNorm); p1_main(bB); return; }
    if (acPass == 17) { if (3 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(3, 4); nvUV = nvCentro(acScreenNorm); p1_main(bA); return; }
    if (acPass == 18) { if (3 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(3, 5); nvUV = nvCentro(acScreenNorm); p1_main(bB); return; }
    if (acPass == 19) { if (3 > nvN()) { fragColor = texture(cB, acScreenNorm); return; } nvUV = nvCentro(acScreenNorm); p2_main(bA); vec4 c = texture(cB, acScreenNorm); fragColor = fragColor + c - fragColor * c; return; }
    if (acPass == 20) { if (4 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(4, 1); nvUV = nvCentro(acScreenNorm); p1_main(bright); return; }
    if (acPass == 21) { if (4 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(4, 2); nvUV = nvCentro(acScreenNorm); p1_main(bA); return; }
    if (acPass == 22) { if (4 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(4, 3); nvUV = nvCentro(acScreenNorm); p1_main(bB); return; }
    if (acPass == 23) { if (4 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(4, 4); nvUV = nvCentro(acScreenNorm); p1_main(bA); return; }
    if (acPass == 24) { if (4 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(4, 5); nvUV = nvCentro(acScreenNorm); p1_main(bB); return; }
    if (acPass == 25) { if (4 > nvN()) { fragColor = texture(cA, acScreenNorm); return; } nvUV = nvCentro(acScreenNorm); p2_main(bA); vec4 c = texture(cA, acScreenNorm); fragColor = fragColor + c - fragColor * c; return; }
    if (acPass == 26) { if (5 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(5, 1); nvUV = nvCentro(acScreenNorm); p1_main(bright); return; }
    if (acPass == 27) { if (5 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(5, 2); nvUV = nvCentro(acScreenNorm); p1_main(bA); return; }
    if (acPass == 28) { if (5 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(5, 3); nvUV = nvCentro(acScreenNorm); p1_main(bB); return; }
    if (acPass == 29) { if (5 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(5, 4); nvUV = nvCentro(acScreenNorm); p1_main(bA); return; }
    if (acPass == 30) { if (5 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(5, 5); nvUV = nvCentro(acScreenNorm); p1_main(bB); return; }
    if (acPass == 31) { if (5 > nvN()) { fragColor = texture(cB, acScreenNorm); return; } nvUV = nvCentro(acScreenNorm); p2_main(bA); vec4 c = texture(cB, acScreenNorm); fragColor = fragColor + c - fragColor * c; return; }
    if (acPass == 32) { if (6 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(6, 1); nvUV = nvCentro(acScreenNorm); p1_main(bright); return; }
    if (acPass == 33) { if (6 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(6, 2); nvUV = nvCentro(acScreenNorm); p1_main(bA); return; }
    if (acPass == 34) { if (6 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(6, 3); nvUV = nvCentro(acScreenNorm); p1_main(bB); return; }
    if (acPass == 35) { if (6 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(6, 4); nvUV = nvCentro(acScreenNorm); p1_main(bA); return; }
    if (acPass == 36) { if (6 > nvN()) { fragColor = vec4(0.0); return; } nvRaio(6, 5); nvUV = nvCentro(acScreenNorm); p1_main(bB); return; }
    if (acPass == 37) { if (6 > nvN()) { fragColor = texture(cA, acScreenNorm); return; } nvUV = nvCentro(acScreenNorm); p2_main(bA); vec4 c = texture(cA, acScreenNorm); fragColor = fragColor + c - fragColor * c; return; }
    if (acPass == 38) { p3_main(cB); fragColor = nvSaida(vec4(fragColor.rgb * fragColor.a, fragColor.a * fragColor.a)); return; }
    fragColor = vec4(0.0);
}
